  const found: Record<string, unknown> = {};
  for (const id of ids) {
    const r = await sdk.linear.searchIssues({ query: `[Sentry] ${id}` });
    found[id] = r.issues.map(i => ({ identifier: i.identifier, title: i.title, state: i.state }));
