}", "input": {}}

{"code": "export async function main(input: Record<string, never>) {
  const res = await sdk.sentry.listIssues({ project: "jobs" });

  const qualifying = res.issues
    .filter(i => i.status === "unresolved" && i.count >= 100)
    .sort((a, b) => b.count - a.count);

  const created = [];
  for (const i of qualifying) {
    const issue = await sdk.linear.createIssue({
      title: `[Sentry] ${i.shortId}`,
      description: i.culprit,
    });
    created.push({ shortId: i.shortId, culprit: i.culprit, count: i.count, linear: issue });
  }

  return {
    threshold: "unresolved AND count >= 100",
    skipped: res.issues
      .filter(i => !(i.status === "unresolved" && i.count >= 100))
      .map(i => ({ shortId: i.shortId, status: i.status, count: i.count })),
    planned: created.length,
    created,
  };
}", "input": {}}

